public static int maxRegions(int N) {
    int regions = 0;
    for (int i = 0; i < N; i++) {
        int r = 1;
        for (int j = 0; j < N; j++) {
            if (j != i) {
                r *= (i + j);
                r %= 1000000007;
            }
        }
        regions = Math.max(regions, r);
    }
    return regions;
}

