public double trimMean(int[] arr) {
    int n = arr.length;
    int min5pct = (int) (n * 0.05);
    Arrays.sort(arr);
    for (int i = 0; i < min5pct; i++) {
        arr[i] = Integer.MAX_VALUE;
        arr[n - i - 1] = Integer.MIN_VALUE;
    }
    double sum = 0;
    for (int i = min5pct; i < n - min5pct; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * min5pct);
}

