public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    if (n % 2 != 0) {
        return false;
    }
    int avg = sum / n;
    int leftSum = 0;
    int rightSum = sum;
    for (int i = 0; i < n / 2; i++) {
        leftSum += nums[i];
        rightSum -= nums[i];
        if (leftSum == avg && rightSum == avg) {
            return true;
        }
    }
    return false;
}

