private static boolean hasAllCodes(String s, int k) {
    Set<String> patterns = new HashSet<>();
    // Generate all possible binary strings of length k
    for (int i = 0; i < k; i++) {
        patterns.add(s.substring(i, i + k));
    }
    // Check if each generated pattern exists in the original string s
    for (String pattern : patterns) {
        if (!s.contains(pattern)) {
            return false;
        }
    }
    return true;
}

