public boolean hasAllCodes(String s, int k) {
    // Initialize a hash set to store all unique substring combinations
    Set<String> substringCombinations = new HashSet<>();

    // Iterate over each substring of length k in the input string s
    for (int i = 0; i < s.length() - k + 1; i++) {
        // Add the substring to the hash set
        substringCombinations.add(s.substring(i, i + k));
    }

    // Return true if the hash set has a size of (2^k) - 1, which means that
    // all possible substrings of length k are present in the input string s
    return substringCombinations.size() == (1 << k) - 1;
}

