    ugly[0] = 1;
    int idx2 = 0, idx3 = 0, idx5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(ugly[idx2] * 2, Math.min(ugly[idx3] * 3, ugly[idx5] * 5));
        ugly[i] = min;
        if (min == ugly[idx2] * 2) idx2++;
        if (min == ugly[idx3] * 3) idx3++;
        if (min == ugly[idx5] * 5) idx5++;
    }
    return ugly[n - 1];
}

