public static List<Integer> lexicalOrder(int n) {
    // Initialize empty list to store the result
    List<Integer> result = new ArrayList<>();
    // Loop through all integers in the range [1, n]
    for (int i = 1; i <= n; i++) {
        // Add current integer to the result list
        result.add(i);
    }
    // Sort the result list in lexicographical order
    Collections.sort(result);
    return result;
}

