    for (int i = 1; i < 10; i++) {
        result.add(i);
        if (i >= n) {
            break;
        }
    }
    for (int i = 10; i <= n; i *= 10) {
        for (int j = 1; j < 10; j++) {
            result.add(i * j);
            if (i * j >= n) {
                break;
            }
        }
    }
    return result;
}

