public static int minPerfectSquareSum(int n) {
    int count = 0;
    int currentNum = 1;
    while (currentNum <= n) {
        int currentSquare = currentNum * currentNum;
        if (currentSquare == n) {
            count++;
            break;
        } else if (currentSquare < n) {
            count++;
            n -= currentSquare;
            currentNum++;
        } else {
            break;
        }
    }
    return count;
}

